import{_ as o,o as l,c as s,a as e}from"./chunks/framework.DzJZdBQK.js";const m=JSON.parse('{"title":"写作课作业-033","description":"","frontmatter":{"date":"2020-08-21T22:08:20","title":"写作课作业-033","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/033.md","filePath":"posts/homework/033.md"}'),a={name:"posts/homework/033.md"};function n(r,t,p,c,u,d){return l(),s("div",null,[...t[0]||(t[0]=[e("blockquote",null,[e("p",null,"8.21写作作业：学习逻辑课“框架效应”，结合生活和工作的经历，谈一下自己的感受和思考，如何为我所用？运用一个类比。")],-1),e("p",null,"框架效应是指一个问题两种在逻辑意义上相似的说法却导致了不同的决策判断。",-1),e("p",null,"“亚洲疾病问题”实验的显示，同一件事改变不同的说法，会使得人们的认知参照点发生改变。而不同的参照点人们对待风险的态度是不同的，面临收益时人们会小心翼翼选择风险规避；面临损失时人们甘愿冒风险倾向风险偏好。",-1),e("p",null,"在生活中，我们也经常受框架效应的影响，比如路边摊，有的摊主会说要不要看下，你可能看也不看就走了，有的摊主会问你要大还是小的，多半你会停下看看。",-1),e("p",null,"告诉小孩不要做某事有奖励，和做了某事要取消奖励，效果就不一样，小孩多半不想被取消奖励。",-1),e("p",null,"正如相对站着的两个人，听到左转并转向后，两个人的朝向已然不同一样，置身于不同的框架的人对同一件事情作出的决策也是不同，甚至截然相反。",-1),e("p",null,"框架效应会对我们工作和生活产生影响，我们可以利用框架效应的正面影响和规避框架效应的负面影响。我们可以多问自己几个问题来规避框架效应的负面影响，比如能换个不同的说法么，调换顺序或者替换反义词一样么?是否有隐含目的？是积极还是消极?",-1)])])}const _=o(a,[["render",n]]);export{m as __pageData,_ as default};
